export function HomeCard({ home, active, saved, onToggleSave, onHover }: HomeCardProps) {
  return (
    <Card
      component="li"
      padding={0}
      radius="md"
      className={classes.card}
      data-active={active || undefined}
      data-home-id={home.id}
      onMouseEnter={() => onHover(home.id)}
